mapper.select:
SELECT , w.node_name AS warehouseName, u.user_name AS userName, u.actual_name AS actualName FROM spd_warehouse_user wu LEFT JOIN spd_org_node w ON wu.warehouse_id = w.node_id LEFT JOIN t_employee u ON wu.user_id = u.employee_id WHERE wu.del_flag = #{delFlag}
AND wu.warehouse_id = #{query.warehouseId}
AND (u.user_name LIKE CONCAT('%', #{query.userName}, '%') OR u.actual_name LIKE CONCAT('%', #{query.userName}, '%'))
AND wu.role_type = #{query.roleType}
AND wu.status = #{query.status}
ORDER BY wu.create_time DESC
